const input = $input.first();
const json = (input && input.json) || {};

let issueKey = '';
let project = '';
let skill = '';
let testFiles = '';
let testCommand = '';

// Ưu tiên trích xuất từ body -> params -> query -> root json
const candidates = [json.body, json.params, json.query, json].filter(c => c && typeof c === 'object');

for (const c of candidates) {
  if (!issueKey && c.issueKey) issueKey = String(c.issueKey).trim();
  if (!project && c.project) project = String(c.project).trim();
  if (!skill && c.skill) skill = String(c.skill).trim();
  if (!testFiles && c.testFiles) testFiles = String(c.testFiles).trim();
  if (!testCommand && c.testCommand) testCommand = String(c.testCommand).trim();
}

// Fallback regex nếu issueKey nằm trong câu lệnh hoặc text
if (!issueKey) {
  const textSource = json.originalCommand || json.text || (json.body && json.body.text) || '';
  const match = String(textSource).match(/\b([A-Za-z0-9]+-[0-9]+)\b/);
  if (match) {
    issueKey = match[1];
  }
}

// 1. Nhận diện nguồn gọi
let triggerSource = json._triggerSource || (json.body && json.body._triggerSource) || 'webhook';
try {
  const trigWebhook = $('Webhook').first();
  if (trigWebhook && trigWebhook.json) {
    triggerSource = 'webhook';
  }
} catch (_) {}
try {
  const trigExec = $('Execute Workflow Trigger').first();
  if (trigExec && trigExec.json && Object.keys(trigExec.json).length > 0) {
    triggerSource = 'executeWorkflow';
  }
} catch (_) {}

if (!issueKey) {
  return [{
    json: {
      error: 'Thiếu tham số issueKey.',
      issueKey: '',
      project: project,
      skill: skill,
      testFiles: testFiles,
      testCommand: testCommand,
      _triggerSource: triggerSource
    }
  }];
}

return [{
  json: {
    issueKey: issueKey.toUpperCase(),
    project: (project || '').trim(),
    skill: (skill || 'run-test').trim(),
    testFiles: testFiles,
    testCommand: testCommand,
    _triggerSource: triggerSource
  }
}];

const { exec } = require('child_process');
const util = require('util');
const fs = require('fs');
const path = require('path');
const execAsync = util.promisify(exec);

const input = $input.first();
const issueKey = (input.json.issueKey || '').toUpperCase();
let project = (input.json.project || '').trim();
const reqTestFiles = (input.json.testFiles || '').trim();
const reqTestCommand = (input.json.testCommand || '').trim();

if (input.json.error || !issueKey) {
  return [{
    json: {
      stdout: '',
      stderr: input.json.error || 'Thiếu tham số issueKey.',
      exitCode: 1,
      error: { message: input.json.error || 'Thiếu tham số issueKey.' },
      project: project,
      issueKey: issueKey,
      cwd: process.cwd()
    }
  }];
}

let cwd = $env.AGENT_WORKSPACE_DIR || process.cwd();

// Đọc danh sách project mapping từ projects.json
let projects = {};
try {
  const projectsFile = path.resolve(cwd, 'projects.json');
  if (fs.existsSync(projectsFile)) {
    projects = JSON.parse(fs.readFileSync(projectsFile, 'utf8'));
  }
} catch (e) {}

// 1. Phân giải thư mục gốc (cwd) theo project hoặc tự động tìm kiếm
if (project) {
  if (projects[project]) {
    cwd = projects[project];
  } else {
    // Kiểm tra trong PROJECT_SCAN_DIRS hoặc thư mục cha
    const scanDirsRaw = (typeof $env !== 'undefined' && $env.PROJECT_SCAN_DIRS) || process.env.PROJECT_SCAN_DIRS || '';
    const scanDirs = scanDirsRaw.split(',').map(s => s.trim().replace(/^["']|["']$/g, '')).filter(Boolean);
    let foundDir = '';
    for (const sDir of scanDirs) {
      const candidate = path.resolve(sDir, project);
      if (fs.existsSync(candidate)) {
        foundDir = candidate;
        break;
      }
    }
    if (foundDir) {
      cwd = foundDir;
    } else if (fs.existsSync(path.resolve(cwd, project))) {
      cwd = path.resolve(cwd, project);
    }
  }
} else {
  // Nếu không truyền project: ưu tiên đường dẫn duy nhất trong projects.json nếu có
  const projectKeys = Object.keys(projects);
  if (projectKeys.length === 1) {
    cwd = projects[projectKeys[0]];
    project = projectKeys[0];
  } else {
    // Nếu có nhiều, tự động tìm xem workspace issueKey nằm ở project nào
    const currentTestDir = path.resolve(cwd, 'workspace', issueKey, 'test');
    if (!fs.existsSync(currentTestDir)) {
      for (const [pName, pPath] of Object.entries(projects)) {
        if (fs.existsSync(path.resolve(pPath, 'workspace', issueKey, 'test'))) {
          cwd = pPath;
          project = pName;
          break;
        }
      }
      if (!fs.existsSync(path.resolve(cwd, 'workspace', issueKey, 'test'))) {
        for (const [pName, pPath] of Object.entries(projects)) {
          if (fs.existsSync(path.resolve(pPath, 'workspace', issueKey))) {
            cwd = pPath;
            project = pName;
            break;
          }
        }
      }
    }
  }
}

// Hàm kiểm tra file test: Tên file luôn bắt đầu hoặc kết thúc bằng "test" (VD: test_*.py, test-*.py, *_test.py, *-test.py), loại trừ conftest.py
function isTestFile(filename) {
  if (!filename.toLowerCase().endsWith('.py')) return false;
  if (filename.toLowerCase() === 'conftest.py') return false;
  const baseName = filename.slice(0, -3).toLowerCase();
  return baseName.startsWith('test') || baseName.endsWith('test');
}

// 2. Định vị file test
const ticketDir = path.resolve(cwd, 'workspace', issueKey);
const stepsDir = path.resolve(ticketDir, 'test', 'steps');
const testDir = path.resolve(ticketDir, 'test');

let matchedFiles = [];
let targetDir = '';

// Nếu caller chỉ định cụ thể file hoặc thư mục testFiles
if (reqTestFiles) {
  const customTarget = path.resolve(cwd, reqTestFiles);
  if (fs.existsSync(customTarget)) {
    const stat = fs.statSync(customTarget);
    if (stat.isFile()) {
      matchedFiles = [path.relative(cwd, customTarget)];
      targetDir = path.dirname(matchedFiles[0]);
    } else if (stat.isDirectory()) {
      try {
        const files = fs.readdirSync(customTarget);
        matchedFiles = files.filter(isTestFile).map(f => path.relative(cwd, path.join(customTarget, f)));
        targetDir = path.relative(cwd, customTarget);
      } catch (e) {}
    }
  }
}

// Nếu chưa tìm thấy qua reqTestFiles, tự động quét stepsDir và testDir
if (matchedFiles.length === 0) {
  if (fs.existsSync(stepsDir)) {
    try {
      const files = fs.readdirSync(stepsDir);
      matchedFiles = files.filter(isTestFile).map(f => path.join('workspace', issueKey, 'test', 'steps', f));
      if (matchedFiles.length > 0) {
        targetDir = 'workspace/' + issueKey + '/test/steps';
      }
    } catch (e) {}
  }

  if (matchedFiles.length === 0 && fs.existsSync(testDir)) {
    try {
      const files = fs.readdirSync(testDir);
      matchedFiles = files.filter(isTestFile).map(f => path.join('workspace', issueKey, 'test', f));
      if (matchedFiles.length > 0) {
        targetDir = 'workspace/' + issueKey + '/test';
      }
    } catch (e) {}
  }
}

// Tách riêng các file performance/benchmark nếu không được chỉ định rõ ràng
if (!reqTestFiles && matchedFiles.length > 1) {
  const functionalFiles = matchedFiles.filter(f => !/perf|benchmark|soak/i.test(path.basename(f)));
  if (functionalFiles.length > 0) {
    matchedFiles = functionalFiles;
  }
}

// Nếu không tìm thấy file test
if (matchedFiles.length === 0) {
  let detailMsg = '';
  if (!fs.existsSync(ticketDir)) {
    detailMsg = 'Thư mục ticket workspace/' + issueKey + ' chưa tồn tại trong dự án ' + cwd;
  } else if (!fs.existsSync(testDir)) {
    const existingDirs = fs.readdirSync(ticketDir).filter(f => {
      try { return fs.statSync(path.join(ticketDir, f)).isDirectory(); } catch(e) { return false; }
    });
    detailMsg = 'Ticket ' + issueKey + ' hiện tại chưa có thư mục kiểm thử `test/` (mới chỉ có các thư mục: ' + (existingDirs.length > 0 ? existingDirs.join(', ') : 'trống') + '). Cần chạy `qa-auto-design` để sinh kịch bản test trước.';
  } else {
    detailMsg = 'Thư mục `workspace/' + issueKey + '/test` đã tồn tại nhưng không tìm thấy file testscript nào (file cần bắt đầu hoặc kết thúc bằng "test", ví dụ: test_*.py, test-*.py, *_test.py).';
  }

  return [{
    json: {
      stdout: '',
      stderr: detailMsg,
      exitCode: 4,
      error: { message: detailMsg },
      project: project,
      issueKey: issueKey,
      cwd: cwd
    }
  }];
}

// 3. Thực thi Pytest với danh sách file tìm được
const quotedFiles = matchedFiles.map(f => '"' + f.replace(/"/g, '\\"') + '"').join(' ');
const runnerCmd = reqTestCommand || 'pytest';
const command = runnerCmd + ' ' + quotedFiles + ' -v --tb=short --timeout=60 -o python_files="test*.py *test.py test-*.py *-test.py test_*.py *_test.py"';

try {
  const result = await execAsync(command, { encoding: 'utf-8', cwd: cwd, timeout: 180000 });
  return [{
    json: {
      stdout: result.stdout || '',
      stderr: result.stderr || '',
      exitCode: 0,
      project: project,
      issueKey: issueKey,
      cwd: cwd,
      matchedFiles: matchedFiles,
      command: command
    }
  }];
} catch (err) {
  return [{
    json: {
      stdout: err.stdout || '',
      stderr: err.stderr || err.message,
      exitCode: err.code !== undefined ? err.code : (err.status || 1),
      error: { message: err.message },
      project: project,
      issueKey: issueKey,
      cwd: cwd,
      matchedFiles: matchedFiles,
      command: command
    }
  }];
}

const fs = require('fs');
const path = require('path');

const input = $input.first();
const extractNode = (typeof $('Extract issueKey') !== 'undefined') ? $('Extract issueKey').first().json : {};
const issueKey = extractNode.issueKey || input.json.issueKey || '';
const project = extractNode.project || input.json.project || '';
const cwd = input.json.cwd || $env.AGENT_WORKSPACE_DIR || process.cwd();
const targetLabel = project ? (project + ' / ' + issueKey) : issueKey;

// Xử lý lỗi Extract
const triggerSource = extractNode._triggerSource || input.json._triggerSource || 'webhook';

if (!issueKey || extractNode.error) {
  const errMsg = extractNode.error || 'Thiếu issueKey hợp lệ.';
  return [{
    json: {
      success: false,
      message: '🚨 **[QA Automation Lỗi]** ' + errMsg + '\n> Cú pháp hợp lệ: `/agent [project] run-test <issueKey>`',
      reportText: '🚨 **[QA Automation Lỗi]** ' + errMsg,
      _triggerSource: triggerSource
    }
  }];
}

// Xử lý kết quả lệnh Execute Command
const execRes = input.json;
let success = true;
let outputText = execRes.stdout || '';
let errText = execRes.stderr || '';

if (execRes.error || (execRes.exitCode !== undefined && execRes.exitCode !== 0)) {
  success = false;
}

// Ghi đè test-output.log và report.md vào workspace/{issueKey}/test/result/
if (cwd && issueKey) {
  try {
    const resultDir = path.resolve(cwd, 'workspace', issueKey, 'test', 'result');
    if (!fs.existsSync(resultDir)) {
      fs.mkdirSync(resultDir, { recursive: true });
    }
    const logPath = path.join(resultDir, 'test-output.log');
    fs.writeFileSync(logPath, (outputText + '\n' + errText).trim(), 'utf8');

    const reportPath = path.join(resultDir, 'report.md');
    const statusText = success ? 'PASSED' : 'FAILED';
    const reportMd = [
      `# Báo Cáo Kiểm Thử Tự Động: ${issueKey}`,
      '',
      `| Thuộc tính | Giá trị |`,
      `| :--- | :--- |`,
      `| **Issue Key** | \`${issueKey}\` |`,
      `| **Project** | \`${project || 'default'}\` |`,
      `| **Trạng Thái** | **${statusText}** |`,
      `| **Thời Gian** | \`${new Date().toISOString()}\` |`,
      '',
      `## Chi Tiết Thực Thi`,
      '```text',
      (outputText + '\n' + errText).trim().slice(-2000),
      '```'
    ].join('\n');
    fs.writeFileSync(reportPath, reportMd, 'utf8');
  } catch (e) {}
}

// Rút gọn output nếu quá dài cho tin nhắn
let logSnippet = (outputText + '\n' + errText).trim();
if (logSnippet.length > 2500) {
  logSnippet = logSnippet.substring(logSnippet.length - 2500);
}

const statusIcon = success ? '✅' : '❌';
const statusText = success ? 'Thành công (Passed)' : 'Thất bại (Failed)';

const message = '🚀 **[QA Automation]** Kết quả chạy kiểm thử cho ticket **' + targetLabel + '**:\n' +
                '- Trạng thái: ' + statusIcon + ' **' + statusText + '**\n\n' +
                '```text\n' + logSnippet + '\n```';

return [{
  json: {
    success,
    message,
    reportText: message,
    issueKey,
    project,
    exitCode: execRes.exitCode,
    _triggerSource: triggerSource
  }
}];
